import java.util.Arrays;
import java.util.Scanner;

public class Main {
    static String readLine(Scanner sc) {
        if (sc.hasNextLine()) {
            return sc.nextLine();
        }
        return "";
    }

    static void permute(char[] chars, boolean[] used, StringBuilder current, StringBuilder out) {
        if (current.length() == chars.length) {
            out.append(current).append("\n");
            return;
        }
        for (int i = 0; i < chars.length; i++) {
            if (!used[i]) {
                used[i] = true;
                current.append(chars[i]);
                permute(chars, used, current, out);
                current.deleteCharAt(current.length() - 1);
                used[i] = false;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = readLine(sc);
        char[] chars = s.toCharArray();
        Arrays.sort(chars);
        StringBuilder out = new StringBuilder();
        permute(chars, new boolean[chars.length], new StringBuilder(), out);
        System.out.print(out);
    }
}

