public class Main {
    static int[][] grid;
    static int rows;
    static int cols;

    static long paths(int r, int c) {
        if (r >= rows || c >= cols || grid[r][c] == 1) {
            return 0;
        }
        if (r == rows - 1 && c == cols - 1) {
            return 1;
        }
        return paths(r, c + 1) + paths(r + 1, c);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        rows = Integer.parseInt(sc.next());
        cols = Integer.parseInt(sc.next());
        grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = Integer.parseInt(sc.next());
            }
        }
        System.out.println(paths(0, 0));
    }
}

